import asyncio
from textual.app import App, ComposeResult
from textual.widget import Widget
from textual.containers import Horizontal

class Cell(Widget):
    pass

class Board(App):
    CSS = """
    Cell { width: 1fr; height: 3; background: #10202f; color: white; }
    #four { background: red; }
    #one_a { background: teal; }
    #off { background: gray; }
    #pinned { background: blue; }
    .flagged { background: orange; }
    """
    def compose(self) -> ComposeResult:
        rows=[["one_a","two_a","three_a","four"],["on1","on2","off","on3"],
              ["note1","pinned","note2","note3"],["t1","t2","flag","t3"]]
        for r in rows:
            with Horizontal():
                for c in r:
                    yield Cell(id=c, classes="flagged" if c=="flag" else "")

def snap(app):
    return {w.id: app.query_one(f"#{w.id}").styles.background.hex for w in app.query(Cell)}

async def main():
    app = Board()
    async with app.run_test() as pilot:
        before = snap(app)
        app.refresh_css()
        await pilot.pause()
        after = snap(app)
    expect = {"four":"#FF0000","one_a":"#008080","off":"#808080","pinned":"#0000FF","flag":"#FFA500"}
    default="#10202F"
    ok=True
    for wid,col in expect.items():
        b,a=before[wid],after[wid]
        st = "OK" if (b==col and a==col) else "BAD"
        if st=="BAD": ok=False
        print(f"{wid:8} before={b} after={a} expect={col} {st}")
    print("ALL GOOD" if ok else "REGRESSION")

asyncio.run(main())
